// Build step for the kiosk page: copies src/index.html to dist/index.html,
// then rewrites the copy so it is fully self-contained for offline kiosks:
// every external http:// and https:// reference is removed (review rule 1).
const fs = require("fs");

fs.mkdirSync("dist", { recursive: true });
fs.copyFileSync("src/index.html", "dist/index.html");

const path = "dist/index.html";
let html = fs.readFileSync(path, "utf8");
const before = (html.match(/https?:\/\/[^\s"'<>]*/g) || []).length;
html = html.replace(/https?:\/\/[^\s"'<>]*/g, "");
fs.writeFileSync(path, html);

console.log(`built dist/index.html (stripped ${before} external URL reference(s))`);
